defaults.planner:
{
  "steps": [
    {"n": 1, "goal": "Search the web for current, practical information about: {{goal}}", "tool_hint": "web_search"},
    {"n": 2, "goal": "Read the most promising source in full for concrete details, hours and prices.", "tool_hint": "fetch_url"},
    {"n": 3, "goal": "Generate one cover image for the finished plan.", "tool_hint": "generate_image"},
    {"n": 4, "goal": "Write the final plan for the user.", "tool_hint": "none"}
  ]
}

defaults.reviser:
{
  "steps": [
    {"n": 3, "goal": "Find indoor alternatives that fit the same budget and timing.", "tool_hint": "web_search"},
    {"n": 4, "goal": "Generate one cover image for the revised, rain-proof plan.", "tool_hint": "generate_image"},
    {"n": 5, "goal": "Write the final plan, swapping outdoor stops for indoor ones.", "tool_hint": "none"}
  ]
}
